#!/bin/bash
# Finish the slimming: drop tracked KPP build artifacts, stop the deleted
# junk from coming back, commit.
set -u
cd /mnt/d/atmos

echo "--- atoms_red (KPP build output, regenerated by build_kpp7.sh):"
ls -la _kppwork/atoms_red atmos_plan/atmos/chemistry/kpp_cb05/atoms_red
head -3 _kppwork/atoms_red

git rm -q --cached _kppwork/atoms_red atmos_plan/atmos/chemistry/kpp_cb05/atoms_red
echo "untracked atoms_red (kept on disk)"

cat >> .gitignore <<'EOF'

# ---------------------------------------- release slimming (2026-09)
# KPP build products (regenerated by build_kpp7.sh)
atoms_red
# one-off logs / bookkeeping removed from the record
/out35.log
_kppwork/calib_run.log
_kppwork/fit_deerpark_2017s.log
_kppwork/co_list.txt
_kppwork/scen_list.txt
EOF

git add .gitignore
git status --short
echo "--- tracked files now: $(git ls-files | wc -l)"